SELECT

FROM msg_info
WHERE delete_state = 0

  AND message_title LIKE CONCAT('%', #{messageTitle,jdbcType=VARCHAR}, '%')


  AND message_type = #{messageType,jdbcType=CHAR}


  AND message_level = #{messageLevel,jdbcType=CHAR}


  AND business_type = #{businessType,jdbcType=CHAR}


  AND `status` = #{status,jdbcType=CHAR}


  AND sender_id = #{senderId,jdbcType=VARCHAR}


  AND create_user = #{createUser,jdbcType=VARCHAR}


  AND create_time BETWEEN #{createTimeStart,jdbcType=TIMESTAMP} AND #{createTimeEnd,jdbcType=TIMESTAMP}


  AND sender_time BETWEEN #{senderTimeStart,jdbcType=TIMESTAMP} AND #{senderTimeEnd,jdbcType=TIMESTAMP}


  AND expire_time BETWEEN #{expireTimeStart,jdbcType=TIMESTAMP} AND #{expireTimeEnd,jdbcType=TIMESTAMP}

SELECT id
FROM msg_info
WHERE delete_state = 0
  AND `status` = #{waitStatus,jdbcType=CHAR}
  AND sender_time IS NOT NULL
  AND sender_time <= #{now,jdbcType=TIMESTAMP}
ORDER BY sender_time
LIMIT #{limit}

SELECT id
FROM msg_info
WHERE delete_state = 0
  AND `status` IN

    #{item,jdbcType=CHAR}

  AND expire_time IS NOT NULL
  AND expire_time < #{before,jdbcType=TIMESTAMP}
  AND fanout_status <> 1
ORDER BY expire_time
LIMIT #{limit}

mapper.update:
UPDATE msg_info SET
  fanout_retry = CASE WHEN fanout_status = 1 THEN fanout_retry + 1 ELSE fanout_retry END,
  fanout_status = 1,
  fanout_time = #{now,jdbcType=TIMESTAMP}
WHERE id = #{id,jdbcType=VARCHAR}
  AND delete_state = 0
  AND `status` = #{doneStatus,jdbcType=CHAR}
  AND (
    fanout_status = 0
    OR (fanout_status = 1 AND fanout_time < #{staleTime,jdbcType=TIMESTAMP} AND fanout_retry < #{maxRetry})
  )

UPDATE msg_info SET
  fanout_time = #{now,jdbcType=TIMESTAMP}
WHERE id = #{id,jdbcType=VARCHAR}
  AND delete_state = 0
  AND `status` = #{doneStatus,jdbcType=CHAR}
  AND fanout_status = 1
  AND fanout_retry = #{retry}

UPDATE msg_info SET
  fanout_status = 3
WHERE delete_state = 0
  AND `status` = #{doneStatus,jdbcType=CHAR}
  AND fanout_status = 1
  AND fanout_time < #{staleTime,jdbcType=TIMESTAMP}
  AND fanout_retry >= #{maxRetry}

