SELECT

FROM msg_info
WHERE delete_state = 0
  AND `status` = #{doneStatus,jdbcType=CHAR}
  AND fanout_status IN (0, 1)
  AND fanout_time < #{staleTime,jdbcType=TIMESTAMP}
  AND fanout_retry < #{maxRetry}
  AND (expire_time IS NULL OR expire_time > #{now,jdbcType=TIMESTAMP})
ORDER BY fanout_time
LIMIT #{limit}
